pub struct PeekMutInner<'a, T, K, S>
where
    T: Ord,
    K: Kind,
    S: VecStorage<T> + ?Sized,
{
    heap: &'a mut BinaryHeapInner<T, K, S>,
    sift: bool,
}

/// Structure wrapping a mutable reference to the greatest item on a
/// `BinaryHeap`.
