impl<T, const N: usize> Clone for Queue<T, N>
where
    T: Clone,
{
    fn clone(&self) -> Self {
        let mut new: Self = Self::new();

        for s in self.iter() {
            // SAFETY: `new.capacity() == self.capacity() >= self.len()`,
            // so no overflow is possible.
            unsafe {
                new.enqueue_unchecked(s.clone());
            }
        }

        new
    }
}

