    for n in [1, 2, 3] { map.insert(n, n).unwrap(); }
    let borrowed: std::vec::Vec<_> = map.iter().map(|(&k, &v)| (k, v)).collect();
    let owned: std::vec::Vec<_> = map.into_iter().collect();
