fn hash_map_operations() {
    let mut actual = heapless::index_map::FnvIndexMap::<u32, u32, 8>::new();
    let mut expected = Vec::<(u32, u32)>::new();
    let mut seed = 94;
    for _ in 0..10_000 {
        let value = next(&mut seed);
        let key = value % 24;
        match value % 5 {
            0 | 1 => {
                let old_index = expected.iter().position(|&(k, _)| k == key);
                let result = actual.insert(key, value);
                if let Some(index) = old_index {
                    assert_eq!(result, Ok(Some(expected[index].1)));
                    expected[index].1 = value;
                } else if expected.len() == 8 { assert_eq!(result, Err((key, value))); }
                else { assert_eq!(result, Ok(None)); expected.push((key, value)); }
            }
            2 => {
                let removed = expected.iter().position(|&(k, _)| k == key).map(|index| expected.swap_remove(index).1);
                assert_eq!(actual.remove(&key), removed);
            }
            3 => {
                actual.retain(|k, _| k % 3 != key % 3);
                expected.retain(|&(k, _)| k % 3 != key % 3);
            }
            _ => {
                actual.entry(key).and_modify(|v| *v += 1);
                if let Some((_, v)) = expected.iter_mut().find(|(k, _)| *k == key) { *v += 1; }
            }
        }
        assert_eq!(actual.iter().map(|(&k, &v)| (k, v)).collect::<Vec<_>>(), expected);
        for k in 0..24 {
            assert_eq!(actual.get(&k), expected.iter().find(|(key, _)| *key == k).map(|(_, v)| v));
        }
    }
}

